// Dependency-free ZIP STORE for round-tripping the small JSON source tree.
const enc=new TextEncoder(),dec=new TextDecoder();
export function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let n=0;n<8;n++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;}
export function zipFiles(files){const parts=[],central=[];let offset=0,size=0;for(const [path,text] of Object.entries(files)){const name=enc.encode(path),body=enc.encode(text),crc=crc32(body),header=new Uint8Array(30+name.length),h=new DataView(header.buffer);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint32(14,crc,true);h.setUint32(18,body.length,true);h.setUint32(22,body.length,true);h.setUint16(26,name.length,true);header.set(name,30);parts.push(header,body);const c=new Uint8Array(46+name.length),v=new DataView(c.buffer);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint32(16,crc,true);v.setUint32(20,body.length,true);v.setUint32(24,body.length,true);v.setUint16(28,name.length,true);v.setUint32(42,offset,true);c.set(name,46);central.push(c);size+=c.length;offset+=header.length+body.length;}
 const end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,central.length,true);e.setUint16(10,central.length,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);const out=new Uint8Array(offset+size+22);let p=0;for(const chunk of [...parts,...central,end]){out.set(chunk,p);p+=chunk.length;}return out;}
export function unzipFiles(bytes){if(bytes.byteLength>5_000_000)throw Error('源文件包超过5MB');const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),files=Object.create(null);let p=0,count=0;while(p+4<=bytes.length&&v.getUint32(p,true)===0x04034b50){if(p+30>bytes.length)throw Error('ZIP损坏');if(v.getUint16(p+6,true)!==0||v.getUint16(p+8,true)!==0)throw Error('请导入编辑器导出的ZIP（不支持外部压缩方式）');const size=v.getUint32(p+18,true),length=v.getUint16(p+26,true),extra=v.getUint16(p+28,true),start=p+30+length+extra,end=start+size;if(end>bytes.length)throw Error('ZIP截断');const path=dec.decode(bytes.slice(p+30,p+30+length));if(!/^(manifest\.json|(?:cards|skills|teams)\/[a-z][a-z0-9_]*\.json)$/.test(path)||files[path]!==undefined)throw Error('ZIP包含非法或重复文件名');const body=bytes.slice(start,end);if(crc32(body)!==v.getUint32(p+14,true))throw Error('ZIP校验失败');files[path]=dec.decode(body);p=end;if(++count>1000)throw Error('源文件数量过多');}if(!files['manifest.json'])throw Error('不是编辑器源文件包');return files;}
